+				setCloudModelIdGlobally(picked.id);
+				setExplicitModelId(picked.id);
+				setModel(picked);
+			}
+		} catch (error) {
+			showToast(`Cline Cloud: ${errorMessage(error)}`, "error");
+		} finally {
+			refocusTextarea();
+		}
